DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='ring_post'; def:=replace(def,'IF NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id','IF public.has_paid_bell(caller) AND NOT EXISTS(SELECT 1 FROM public.messages WHERE post_id=p.id'); EXECUTE def; SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='ring_vehicle_board'; def:=replace(def,'IF NOT EXISTS(SELECT 1 FROM public.messages WHERE sender_id=caller','IF public.has_paid_bell(caller) AND NOT EXISTS(SELECT 1 FROM public.messages WHERE sender_id=caller'); EXECUTE def; END $$;